<?php if($historical): ?><nav class="historical-pagination" aria-label="Pagine della trascrizione"><?php foreach([[$page-1,'Messaggi precedenti'],[$page+1,'Messaggi successivi']] as [$p,$label]):if($p<1||$p>$pages)continue; ?><a class="action-btn" href="?azione=storico&amp;historic_id=<?=$historyId?>&amp;page=<?=$p?>"><?=$label?></a><?php endforeach; ?></nav><?php endif; ?>
